// GENERATED by tracker/scripts/sync-site-changelog.js from src/pages/log.html — the site's changelog cards for
// the tracker's Help > Patch notes "Site" tab. Edit the site page, then re-run the script; tests/sitesync.test.js
// fails when this copy drifts. Newest first: [site version, data-t, card title, pill label or null, card body html].
(function (root){
  const LOG = [
    ["0.19.16","2026-10-31T06:52:01Z","Oct 31, 2026 · Privacy page covers shop prices and the delete button",null,"<p>The <a href=\"https://maplestory.scumlord.studio/#g=privacy\" target=\"_blank\" rel=\"noopener\">Privacy</a> page now says what the tracker's shop-price sharing sends (item, quantity, price, sold-out flag, never a seller or character), that KPQ rounds carry a board name you can make up, and how to erase everything a tracker copy shared: Settings &gt; Window and sharing &gt; <b>Delete what I shared</b> in Grind Tracker 0.3.28. Shop prices also now count one vote per tracker, so a single copy sending hundreds of rows can't move a price.</p>"],
    ["0.19.15","2026-10-31T06:33:14Z","Oct 31, 2026 · Screenshot import tested at every size",null,"<p><b>Character Builder</b> \"Import from screenshots\" is now checked at 14 game sizes from 1x to 3x, smoothed and blocky, using Danny's own Hunter. Four sizes misread and are fixed: blocky 1.875x and 2.5x (mistaken for 2x), smoothed 3x (lost STR to LUK), and shrunk screenshots that read the wrong level.</p>"],
    ["0.19.14","2026-10-31T05:31:01Z","Oct 31, 2026 · Changelog set straight",null,"<p>A pass over this page's order: a few entries that were carded later about earlier work sat at their old spot in the list, so the days read out of order and those versions carried numbers out of step with their dates. The list is strictly newest-first now, and the affected entries (and the ones between) renumbered to match. Nothing was rewritten or removed.</p>"],
    ["0.19.13","2026-10-31T05:10:55Z","Oct 31, 2026 · Screenshot import reads any game size",null,"<p><b>Character Builder</b> \"Import from screenshots\" used to need the game at exactly 100% or 200% size; a tester's screenshot at 1.875x came back \"Nothing recognized\". Now it measures the scale from the Character Stat window's labels and reads level, stats and worn armor at any size. Weapons and skill levels can still be missed on these smoothed shots, so the note asks you to check them.</p>"],
    ["0.19.12","2026-10-31T03:36:46Z","Oct 31, 2026 · Classicrank is parked until its source is back",null,"<p>classicrank.com stopped answering, so its pieces on our pages are tucked away for now: Load by IGN, the @char search, the job census card and character profile links. They come back when the source does.</p>"],
    ["0.19.11","2026-10-31T03:36:46Z","Oct 31, 2026 · KPQ leaderboard: tracker rounds only",null,"<p>The leaderboard starts fresh and only counts rounds tracked with the <a href=\"https://maplestory.scumlord.studio/#g=trk\" target=\"_blank\" rel=\"noopener\">Grind Tracker</a> app: the in-page timer still times your runs, but it no longer posts to the boards (the server accepts tracker rounds only), so every scored round comes from the same reader and the same scoring. The old board data was retired.</p>"],
    ["0.19.10","2026-10-30T16:32:41Z","Oct 30, 2026 · The sleek look is now the default",null,"<p>The site wears the Elv scheme out of the box: near-black panels, the purple accent, quiet lines. The classic purple look is still here: open Settings &gt; Theme and pick <b>Clanker Chic</b> to bring it back (it was called Default before). The Grind Tracker and its overlay switched to the same default, so all three match without touching a slider.</p>"],
    ["0.19.9","2026-10-30T02:00:00Z","Oct 30, 2026 · Builder: what one more point is worth",null,"<p>The Character Builder has a new card that re-runs its own damage model with +1 STR, DEX, INT, LUK and +1 weapon attack and shows the damage per second each one adds (misses included), with the best one at 100%. Idea borrowed from SimulationCraft's scale factors; the numbers come only from the builder's existing sourced formulas.</p>"],
    ["0.19.8","2026-10-29T23:00:00Z","Oct 29, 2026 · Builder: Bow Mastery crit rate and a stat window row",null,"<p>The Character Builder showed 26% crit for a Lv 41 Hunter whose in-game stat window says 36%: weapon masteries that add Critical Rate (Bow Mastery +10%) or Critical Damage (Blunt and Crossbow Mastery +20%) were skipped. All masteries now count. Physical builds also get a \"Stat window\" row, the plain attack range without the skill's %, so you can compare it with the in-game ATTACK line.</p>"],
    ["0.19.7","2026-10-29T20:26:50Z","Oct 29, 2026 · KPQ: five scored boards",null,"<p>The Kerning City Party Quest leaderboard grew into five scored boards — Best full run, Rush, Bonus, What could have been and Average score. Rounds tracked with the Grind Tracker (0.3.20 and on) are scored on the server: Rush points from stage speed against your own recorded average, Bonus points from EXP, mesos and drops at their NPC sell value, with small per-item bonuses and a big one for a Pan Lid. The KPQ page has a Scored boards card with the rankings, and how the points work is written under the table.</p>"],
    ["0.19.6","2026-10-29T18:20:00Z","Oct 29, 2026 · Game update v1.1.0 data","game data","<p>The site's game data now matches Classic World v1.1.0 (Oct 29 maintenance), read from the OSMS export. Clang, Copper Drake, Drake and Tortie have less HP. Poison Breath and Thunder Bolt hit 10 harder at every level, and Archer Focus gives more Accuracy. Spearman Final Attack absorbs at most 15% of Max HP (was 25%), and Rush at Lv 10 reaches 150 range (was 130). The Bow and Crossbow arrow swap recipes now trade 100 for 50. Nexon had not posted its own notes when this went up, so these are client-data changes only.</p>"],
    ["0.19.5","2026-10-29T00:30:00Z","Oct 29, 2026 · Readable tracker patch notes",null,"<p>Grind Tracker patch notes on the Tracker page now show each version as a heading line with one bullet per change instead of one block of text.</p>"],
    ["0.19.4","2026-10-28T14:24:35Z","Oct 28, 2026 · Price accuracy: full-pipeline audit fixes",null,"<p>A bug hunt that re-derived every rule behind the price headlines against the raw data for all 2,258 items found three real defects, all fixed. <b>3-day weighted headlines were applied backwards</b>: the weights listed today as the heaviest but the code gave the oldest of the three days 0.5 and today 0.2, so a moving price under-reacted to the very move it was reporting - all 119 moving items now weight today at 0.5 as documented, and the weights stay aligned with the newest day even when a day is missing from history. <b>The consensus tile under-counted its evidence</b>: \"consensus of N markets\" printed N as the sales count, so a median drawn from 41 sales read as \"2 sales\"; it now counts the actual sales behind the pooled markets. <b>The likely range could contradict its own headline</b>: when the spike breaker holds yesterday's median, the p25-p75 band still describes today's sales, so an item could read \"Usual 469, likely 62-275\"; the band now hides while a hold is active. The same audit also drives a new accuracy scene in the test suite (weight direction, hole alignment, consensus counting, held-band suppression), and a job census card fix: the card's render path is tested with a patched build, so the quiet state that ships while the classicrank read key is pending is asserted too.</p>"],
    ["0.19.3","2026-10-28T01:29:05Z","Oct 28, 2026 · Where to buy: only shops that can still be open",null,"<p>Item pages now treat a listing's age as trust, because people leave shops up while they sleep or work - about 8-12 hours. Listings 8 hours old or newer come first (cheapest within that group), and the <b>Cheapest listed</b> tile quotes one of them whenever one exists. Listings 8-12 hours old carry a <b>low-confidence</b> tag: the shop may have closed. Anything older hides behind a <b>Show older</b> button that says shops may have closed, so stale shops only appear when asked for - and when every listing on an item is that old, they all show with a clear warning that these are price hints, not live quotes. The same trust rules now apply to Buy orders.</p>"],
    ["0.19.2","2026-10-27T23:49:46Z","Oct 27, 2026 · Prices: honest about thin and moving data",null,"<p>Five changes from the accuracy round. <b>Spike breaker</b>: a fresh median built on fewer than 5 sales that lands more than 3x off yesterday is held at yesterday's value and marked, instead of publishing a one-sale spike. <b>Likely range</b>: items whose middle half of sales spans more than 40% of the median, or that lack data, show a likely range (from their own p25-p75) instead of a single number that pretends precision. <b>Price moving flag</b>: when the last two daily medians disagree by more than 25%, the tile says so. <b>3-day weighted</b>: for those moving items the Usual price follows a weighted average of the last three daily medians (today heaviest), while the Prices row keeps the raw median. <b>Consensus for thin items</b>: a thin meso.watch median no longer headlines when two or more solid markets (classicmarket combined, maplestory.watch, mesoindex, each at 5+ sales) agree on a pooled median - it is labelled \"consensus of N markets\", and meso.watch keeps the headline whenever it is solid. Audit proposals P12-P16.</p>"],
    ["0.19.1","2026-10-27T20:38:57Z","Oct 27, 2026 · Faster visits: prices split from the page",null,"<p>The market data now loads from its own file instead of riding inside the page itself. Before, every price poll re-served the whole page to every returning visitor; now your device caches the page and only the price file re-downloads when prices move, at about a quarter of the bytes. First visits are lighter too: about 1.2 MB compressed instead of 1.5. Nothing changes on the surface, and offline works as before. Audit proposal P9.</p>"],
    ["0.19.0","2026-10-27T16:27:30Z","Oct 27, 2026 · Movers page","new page","<p>The biggest day-over-day price changes, one row per item and market, under Mesos and Trade. Each row compares a market against its own yesterday number, from fields the polls already store: meso.watch's published daily medians and maplestory.watch's stored day-ago typical, with a sparkline on the meso.watch rows. Each market is only ever compared with itself, so the wording differences between sites never touch the math. Filter by direction, item type, sales floor and sort by biggest move, biggest rise or biggest fall. Audit proposal P8.</p>"],
    ["0.18.11","2026-10-27T15:45:45Z","Oct 27, 2026 · Monster pages: players' actual mesos",null,"<p>Monster pages now show what tracker players actually earn next to the estimate: when 100 or more Grind Tracker kills are shared for a monster, the Mesos block adds a <b>players' actual</b> line with the mesos per kill, the kill count behind it, and how far meowdb's estimate sits from it. Pig today: 15.1 mesos per kill over 1,337 kills, with the estimate 14% under; Ribbon Pig's sits 38% over. The comparison grows as more runs are shared; the Where to train model itself is unchanged.</p>"],
    ["0.18.10","2026-10-26T15:50:00Z","Oct 26, 2026 · Prices: closer to their sources",null,"<p>Three changes from the overnight price audit. <b>More items get a price</b>: the usual-price chain now ends with the shop-scan sources (mesoarbitrage, then maplestory.watch, then mesoindex) for the 51 items the first five sources price but the old chain missed; scan prices carry the same rough flag when their data is thin. <b>Sources context on the Usual price tile</b>: a second line shows the range across every source with real data behind it, plus a pill that says whether they sit within 25% of each other or fall far apart. <b>Stale tints on the Prices table</b>: a source whose data is past its update cadence gets a stale pill, so a frozen source is visible on the page instead of only in CI.</p>"],
    ["0.18.9","2026-10-26T02:10:00Z","Oct 26, 2026 · KPQ: Today's runs in arrival order",null,"<p>Today's runs now reads like a log: rounds list in the order the server received them, each with its own recorded time (shown in your time), and the day's best round is highlighted wherever it sits in the day. The times come from a new <b>at</b> field the tracker server now publishes with every round. Rounds recorded before the times were kept keep the fastest-first list.</p>"],
    ["0.18.8","2026-10-26T00:55:00Z","Oct 26, 2026 · KPQ leaderboard: Today's runs",null,"<p>The Kerning PQ leaderboard gains a <b>Today's runs</b> card under the board: every round recorded today, fastest first, with the day's best highlighted and one click from its stage times. It ignores the board filters, so the whole day stays visible even when the board is filtered down, and quiet days say when the latest round on file was run. The About box explains what it counts.</p>"],
    ["0.18.7","2026-10-25T21:55:00Z","Oct 25, 2026 · Quest pages: Where to go",null,"<p>Quest pages now open with a <b>Where to go</b> section near the top: the giver's map moved up from the bottom of the page and gained the trip's whole picture. The map carries the numbered exits, the star on the giver and a colored dot for every monster spawn spot on that map, with a legend underneath (the quest's own targets in bold). Monsters the quest needs that live somewhere else are listed with their best spawn maps and counts. Also fixes the giver's star rendering as plain text under the map on quest pages.</p>"],
    ["0.18.6","2026-10-25T21:25:00Z","Oct 25, 2026 · Quest pages","new","<p>Every quest name in the database is clickable now and opens the quest's own page: the story, what it takes to accept it (requirements and the quests it comes after), what it asks for, the full rewards with what they're worth at player prices and the community verdict, the whole questline in order with the previous and next quest, the NPC who gives it and where they stand, and the quests it stacks with. Works from the quest table, Search everything, item and monster pages, the Path Planner, the Quest log and Citizenship.</p>"],
    ["0.18.5","2026-10-25T19:13:00Z","Oct 25, 2026 · Wording cleanup",null,"<p>Small wording fixes in the help boxes on <b>Quest log</b>, <b>Where to train</b> and <b>Keep or sell</b>: lines that meant \"only\" now say \"only\". Nothing moved and nothing behaves differently.</p>"],
    ["0.18.4","2026-10-25T16:27:00Z","Oct 25, 2026 · Deals in Search everything",null,"<p>Type <b>@deal</b> in <b>Search everything</b> (Ctrl+K) for the current bargains: items whose cheapest live listing sits at least 10% under the middle price across the sites we pull, best first. A result reads like \"23% under usual · cheapest 850,000 (median 1,100,000)\" and opens the item's page. Equips stay out, and the score is the Market Comparison Index's own deal computation, so the two agree.</p>"],
    ["0.18.3","2026-10-25T16:24:00Z","Oct 25, 2026 · Market Comparison Index: source health and 7-day trends",null,"<p>The <b>Market Comparison Index</b> gains two reads on its own data. A <b>source health</b> strip shows how fresh each price site's numbers are and flags a source past its poll cadence, so an old read is visible instead of quietly skewing its column. A <b>7-day</b> column shows meso.watch's rolling sale-price trend per item as a sparkline with an arrow (down means getting cheaper), and a <b>7-day trend</b> sort brings the movers to the top.</p>"],
    ["0.18.2","2026-10-23T18:12:00Z","Oct 23, 2026 · Victoria Island: walking trip times",null,"<p>The Map Navigator card on the <b>Victoria Island</b> section page now quotes the on-foot trip the way the full Map Navigator's <b>No taxi</b> box does: the walking route, map by map, no cab fare. <b>Show the route</b> opens the full navigator with No taxi already ticked.</p>"],
    ["0.18.1","2026-10-23T01:00:00Z","Oct 23, 2026 · Section pages",null,"<p>Click a section title in the sidebar (<b>Grind Tracker</b>, <b>Training</b>, <b>Victoria Island</b>, <b>Maple Database</b>, <b>Mesos and Trade</b>) for that section's own page: what each page in it does, with a small live example to try, like an item search, a monster card, EXP to your next level, a town-to-town trip time or an item's going price.</p>\n      <p>Grind Tracker's Overview is now its section page; old links still open it. On phones and in Two rows, each section starts with an Overview pill.</p>"],
    ["0.18.0","2026-10-23T00:20:00Z","Oct 23, 2026 · Changelog links",null,"<p>Page and section names in the <b>Changelog</b> are now links: click <b>Quest log</b> or <b>Mesos and Trade</b> to go there. The page is one centered column now, with no empty space to the right.</p>"],
    ["0.17.4","2026-10-22T23:52:53Z","Oct 22, 2026 · Quest log plans crafting with your own craft levels",null,"<p>Crafting is your own skill in Classic World, so the Quest log's route now crafts quest items with your levels from <b>Crafting › Your craft levels</b>, right where you are, and shows the craft EXP you'll get. Items above your level (or in a profession you haven't learned) are planned as <b>Buy from players</b> at the usual price, with the level that would let you make them.</p>"],
    ["0.17.3","2026-10-22T21:30:00Z","Oct 22, 2026 · Citizenship moved",null,"<p><b>Citizenship</b> is now under <b>Maple Database</b> (after Skills). Old links still work.</p>"],
    ["0.17.2","2026-10-22T20:20:00Z","Oct 22, 2026 · Quest log checks its reads",null,"<p>The Quest log reader now checks itself. A row it isn't sure of is no longer added: it asks you to pick the right quest. The state (done or in progress) comes only from the tab it can see. The selected (highlighted) row is read too, and each category's count on the game's bar is checked against the rows read.</p>"],
    ["0.17.1","2026-10-22T19:55:00Z","Oct 22, 2026 · Quest log reads your screen",null,"<p><b>Quest log</b> no longer needs a recording: press <b>Read my screen</b>, share the game window and scroll through your QUEST window. Quests fill in as they're read, with the names shown so a wrong one is easy to spot. <b>Undo</b> / <b>Redo</b> take back a read. Dropping a recording or screenshots still works.</p>"],
    ["0.17.0","2026-10-22T19:44:08Z","Oct 22, 2026 · Market Comparison Index",null,"<p>New page under Mesos and Trade: every price site we pull side by side, one row per item (meso.watch, maplestory.watch, mesoindex.com, mesoarbitrage.com, classicmarket.kr, meowdb). The cheapest site for each item is green, the most expensive amber, with the middle price, how far the sites disagree and the cheapest live listing seen in the last day. Hover an item for its tooltip, click it for its page.</p>"],
    ["0.16.1","2026-10-22T19:10:00Z","Oct 22, 2026 · Market today on Home",null,"<p>The <b>Mesos and Trade</b> card on Home now shows <b>Market today</b>: how many player-shop sales meso.watch is tracking and the biggest recent sale (click the item for its page).</p>"],
    ["0.16.0","2026-10-22T16:42:38Z","Oct 22, 2026 · Quest log: read your quests, plan the route","new","<p>New <b>Quest log</b> page (Training). Record your in-game QUEST window while you scroll through the <b>Completed</b> tab and then <b>In Progress</b>, drop the video (or screenshots) on the page, and it reads every quest name, in your browser. It then lists what you're on, what you can take on now at your level, and what opens within 5 levels, all from the game files.</p>\n      <p>Tick any quests and <b>Plan</b> makes one route for all of them, adding the earlier quests they need: where to accept, each monster hunted once for every quest that wants it, shop items to buy, items to craft (and their materials), and where to turn in, in the order with the least walking and killing. Done quests also count in <b>Keep or sell</b>.</p>\n      <p>Also: the Quest Database now shows each quest's <b>questline</b> by name (like \"Icarus's Dream\"), the same name the in-game quest log shows, and searching a questline finds its quests.</p>"],
    ["0.15.0","2026-10-22T01:26:06Z","Oct 22, 2026 · EXP/hr live from your screen","new","<p>The <b>EXP/hr calculator</b> can now watch your game like the Grind Tracker app does, right in the browser (so macOS works too). Press <b>Share game window</b>: it reads your EXP bar and pickup lines and shows EXP, mesos and kills per hour, loot value, potions used, level-ups and time to level, with idle time and Cash Shop trips left out. <b>Pause</b> for breaks, <b>Stop and save</b> puts the run in your saved sessions (now with Mesos/hr), and <b>Mini view</b> (Chrome, Edge) keeps the numbers in a small window over the game. Pick your map and class on the page; the browser can't read them off the screen.</p>\n      <p>Also: drop two screenshots (start and end) to fill in the calculator from their EXP bars and times, and <b>Save as image</b> makes a picture of your result to share. Nothing is uploaded.</p>"],
    ["0.14.2","2026-10-22T01:20:00Z","Oct 22, 2026 · New content: Excavation Site, Remains, Stumpy",null,"<p>Game data updated to the OSMS Oct 21 release: <b>Excavation Site I-III</b>, <b>Remains &lt;Tomb&gt; I-IV</b>, <b>Remains &lt;Cliff&gt;</b>, <b>Camp 1-3</b>, Parched Land and The Murky Swamp II, with 9 new monsters (Ghost Stump, Wooden and Rocky Mask, Skeledog, Mummydog, Skeleton Soldier/Officer/Commander), the boss <b>Stumpy</b>, 37 items and 18 recipes. Where to train ranks the new maps, and Monsters has a <b>Primrose Hill PQ</b> type.</p>\n      <p><b>World Map:</b> maps the in-game world map has no dot for (the new areas, the Kerning subway and a few others) are now listed with the nearest dot you can walk to, so map and monster search find them.</p"],
    ["0.14.1","2026-10-22T01:15:50Z","Oct 22, 2026 · Crafting, all in one place",null,"<ul><li>The Craft planner is now the <b>Plan</b> tab of <b>Crafting</b>, next to <b>Recipes</b>, <b>Level up</b> and <b>Reference</b> (masters, craft levels, raw materials). Old Craft planner links open Plan.</li>\n        <li><b>Your craft levels</b> sit at the top, set once for every tab.</li>\n        <li><b>Recipes</b> show <b>Sells for</b> and <b>Profit</b> (sortable), with <b>Only my levels</b>, <b>Profitable only</b> and a \"you can make N\" badge from your inventory screenshots.</li>\n        <li>Click any recipe for a pop-up: prices, ingredients (what you have, worth, cheapest buy), the from-scratch parts, where to farm the materials, what it's used in, and every price source.</li>\n        <li><b>Level up</b> starts from your craft level and can value materials at market price.</li></ul>"],
    ["0.14.0","2026-10-22T00:03:22Z","Oct 22, 2026 · Grind Tracker: where your data lives",null,"<p><b>How to use</b> now lists the tracker's folders (settings and History, bug reports, run pictures) and how to uninstall it.</p>"],
    ["0.13.9","2026-10-21T20:23:29Z","Oct 21, 2026 · Who plays what, and @char in search",null,"<p>Character Builder gets a <b>Who plays what</b> card: how many Windia characters on classicrank.com play each job, each job's share, its top level and the level job rank #100 needs, with your builder job highlighted and ranked. Refreshed daily. The Load by IGN badge now says \"Spearman #1 of 2,632\".</p>\n      <p>Search (Ctrl K) takes <b>@char</b> and a name: it shows the character's sprite, level, job and ranks, and Enter loads it into Where to train (if open) or the Character Builder.</p>"],
    ["0.13.8","2026-10-21T20:22:18Z","Oct 21, 2026 · Polish pass two",null,"<ul><li><b>Path Planner</b> opens with four number tiles (time, mesos, route, grinding only); the working is under <b>How these numbers are worked out</b>.</li>\n        <li><b>EXP/hr calculator</b>: one tidy form with Start timer next to Minutes, and a short note instead of an empty Saved sessions table.</li>\n        <li>Screenshot boxes (Price check, Craft planner, Character Builder) get a picture icon and a <b>Browse</b> button instead of the browser's own file button.</li>\n        <li><b>Quests</b>: \"Stack with\" is a small \"stacks with N\" chip that opens the list, so rows stay short.</li>\n        <li>Monster pages: the best-maps table fits next to the minimap, or sits above it on narrower windows.</li>\n        <li>Same heading sizes on every page. Craft planner explains its empty \"From your inventory\" box.</li>\n        <li>Phones: menu rows fade at the edges and center the page you're on; a dropdown too narrow for its choice takes the whole row; the footer version line no longer breaks mid-phrase.</li>\n        <li>Grind Tracker <b>How to use</b>: play at your monitor's native resolution.</li></ul>"],
    ["0.13.7","2026-10-21T20:06:28Z","Oct 21, 2026 · Where to train fits on a normal screen",null,"<p>At desktop width the Where to train table no longer hides <b>Est. EXP/hr</b>, <b>Mesos/hr</b> and <b>Hrs / level</b> off to the side. The potions trip moved under the map name, the hit chance sits under the danger pill and the relative bar sits under EXP/hr. Items and Citizenship tables also fit their cards now.</p>"],
    ["0.13.6","2026-10-21T19:43:52Z","Oct 21, 2026 · mesoindex.com prices + shops",null,"<p>Item pages get a <b>mesoindex.com</b> row in <b>Prices</b> (its usual price for about 1,000 items, the range half of sales fell in, cheapest ask, sales in the last 7 days), and <b>Where to buy</b> now lists mesoindex shops seen in the last day with channel, FM room (or the map, for shops outside the FM) and seller. mesoindex reads Free Market shops from players' scans (mostly via cozy.markets). Used with the owner's OK.</p>"],
    ["0.13.5","2026-10-21T19:26:12Z","Oct 21, 2026 · Load your character by name",null,"<p><b>Load by IGN</b> on Character Builder and Where to train: type your character's name and the site asks classicrank.com for it, shows your sprite, level, job, overall and job rank and when you last levelled, and sets your class, 2nd job and level. 3rd jobs count as their 2nd job; Beginners and Pirates set the level only. Nothing is sent until you press Load.</p>"],
    ["0.13.4","2026-10-21T18:02:48Z","Oct 21, 2026 · Says why there are no live listings",null,"<p>meso.watch hasn't published live Free Market listings since Oct 17, so FM Sniper and \"Cheap in shops now\" have had nothing to show. The footer and FM Sniper now say so (\"meso.watch's newest list is from Oct 17\") instead of looking empty. Sale prices are unaffected.</p>"],
    ["0.13.3","2026-10-21T17:44:47Z","Oct 21, 2026 · Home cards close up on wide screens",null,"<p>On screens 1,700 px and wider, Home left big empty gaps under each card (bigger under taller cards, and bigger at larger page sizes). Cards in a column now sit one small gap apart at every width and page size.</p>"],
    ["0.13.2","2026-10-21T17:37:39Z","Oct 21, 2026 · Page names in the browser tab, page links, KPQ timer on Home",null,"<p>The browser tab now names the page you're on (like \"Items · MS Classic World Data Slop\"), so several open tabs and your history are easy to tell apart.</p>\n      <ul><li>Links can open one page: add <b>#g=</b> and the page, like <b>#g=kpqt</b> for the KPQ timer.</li>\n        <li>Home's Grind Tracker card now links the KPQ timer.</li>\n        <li>On phones and tablets, \"About this page\" and the other fold-out headers are bigger to tap.</li></ul>"],
    ["0.13.1","2026-10-21T17:13:34Z","Oct 21, 2026 · Item pages reordered, and a way to reset the site",null,"<p>Item pages now go stats, then <b>Where to get it</b> and <b>What it's for</b>, then <b>Prices</b>.</p>\n      <p>Settings has a new <b>Reset</b> section: <b>Reset look and layout</b> puts the theme, menu style, page size and header/sidebar back to how the site comes (your saved profiles and themes stay), and <b>Erase everything this site saved</b> makes it like a first visit. Both ask for a second click first.</p>"],
    ["0.13.0","2026-10-21T16:09:00Z","Oct 21, 2026 · KPQ timer and a better KPQ leaderboard","new","<p>New <b>KPQ timer</b> page (Grind Tracker): time Kerning PQ rounds stage by stage with the space bar, see each stage against your best, sum of best and averages, and keep your rounds in this browser. Share your game window and it reads the in-game KPQ clock, so rounds start by themselves and follow the game's time. Turn on sending to put cleared rounds on the leaderboard with your name.</p>\n      <p>The <b>KPQ leaderboard</b> gets filters (Rush or Bonus, party size, job, period, timed by), each round's stage times on a click, a Fastest stages card, an About box, and your own line highlighted. The server now drops repeats of the same round and keeps where each round was timed. Fixed for the Grind Tracker's next release: the KPQ clock never read seconds ending in 6 or 9.</p"],
    ["0.12.10","2026-10-21T16:05:00Z","Oct 21, 2026 · Tables fit on phones",null,"<p>On a phone, wide tables (Monsters, Skills, Items, Quests, Where to train, Path planner, Crafting, FM Sniper and the rest) no longer hide columns off to the side. Each row becomes a small card: the name on top, every other column as a labelled value underneath. Sort buttons stay above the list. Craft levels turn on their side, one row per level.</p"],
    ["0.12.9","2026-10-21T15:49:36Z","Oct 21, 2026 · Polish pass: consistent controls and tidier pages",null,"<p>Every list page (Items, Monsters, Skills, Quests, Keep or sell, World Map, Where to train, FM Sniper) now has <b>Reset filters</b> and <b>Copy link</b> side by side at the end of its filter row; a list link opens the page with the same filters. The changelog shows the time each version went out (in your time zone; older versions read back from the site's history) and folds older days under their date.</p>\n      <ul><li>Home cards keep their own height, and More now links Feedback and Privacy.</li>\n        <li>Where to train opens with a short summary; the full working is under <b>How these numbers are worked out</b>.</li>\n        <li>Keep or sell's table fits its card; FM Sniper's six stat tiles sit on one row; Crafting's sections are cards.</li>\n        <li>Item pages: the header and stats sit in a card, effects like \"Restores 100 HP\" stay on one line, and Prices says \"today\" or \"2 days ago\" instead of a bare date.</li>\n        <li>World Map lists the best 3 spots for your class and level until you click a dot. Map Navigator is one centered column.</li>\n        <li>Quest rewards lead with one number (net, or the reward's value), the parts below it, sources on hover.</li>\n        <li>Phones: filter buttons share rows, boxes fill their row, no \"Ctrl K\" hint on touch screens.</li>\n        <li>Grind Tracker: a step-by-step for the Windows \"protected your PC\" warning on the download card, and a preview row on the empty Shared runs page.</li></ul"],
    ["0.12.8","2026-10-21T11:37:40+00:00","Oct 21, 2026 · classicmarket.kr market prices",null,"<p>Item pages get a <b>classicmarket.kr market</b> row: classicmarket.kr's own combined price for about 1,100 items, with units sold, units seen, the low-high range and how many are for sale now. Used with the owner's OK. Where meso.watch has no sales, the site's usual price now falls back to it before meowdb and the classicmarket.kr trade posts.</p"],
    ["0.12.7","2026-10-21T11:22:58+00:00","Oct 21, 2026 · Two more price sources: mesoarbitrage.com + maplestory.watch",null,"<p>Item pages' <b>Prices</b> table gets two rows from sites that read Free Market shops off players' shared game windows: <b>mesoarbitrage.com</b> (median sale, cheapest ask, last 72 hours) and <b>maplestory.watch</b> (typical price over 14 days, lowest, how many are for sale, trend vs a day ago). <b>Where to buy</b> now also lists maplestory.watch shops seen in the last day, with seller, FM room and channel when known. Updated every 3 hours. The usual price the rest of the site uses stays on meso.watch, which has about 10× more sales.</p"],
    ["0.12.6","2026-10-21T11:06:39+00:00","Oct 21, 2026 · Item prices at a glance + meowdb market",null,"<p>Item pages get a cleaner <b>Prices</b> section: four big numbers up top (usual price, cheapest listed, NPC shop, NPC buy-back), then one row per market source with its price, how many sales or posts it's based on and when it was updated. New: <b>Where to buy</b>, every live listing we know a place for (channel, FM room, spot, seller), cheapest first, so if one shop is gone you can try the next. Prices and listings now also come from <b>meowdb</b>'s Free Market (players' price checks and the shops they post, refreshed every 3 hours); where meso.watch has no sales, the site uses meowdb's usual price before classicmarket.kr.</p"],
    ["0.12.5","2026-10-21T10:54:41+00:00","Oct 21, 2026 · Kill and accuracy breakpoints",null,"<p>Where to train: every map now has a kill badge under its monsters, e.g. <b>3-hit sure · 1-hit 51%</b>: the hits that always kill its most common monster, and the fastest kill that happens at least half the time. Click it for each monster on the map and the <b>+W.Atk</b> (or Magic ATT) or <b>+main stat</b> that makes one fewer hit a sure kill. The Hit column shows the <b>+Accuracy</b> to hit everything there 100%, and the details list +Acc for 95% and 100% per monster. Uses your damage range (Character Builder hand-off, typed Magic and INT, or the default build) after the monster's defense, level penalty and element; an estimate that assumes each hit rolls evenly between min and max. No badge when there is no real damage range (the 20 × level guess has none); a typed Attack range alone shows hits but not +W.Atk, since its stat split is unknown.</p"],
    ["0.12.4","2026-10-21T10:49:02+00:00","Oct 21, 2026 · Quest turn-in value",null,"<p>Quests and Citizenship now show what a quest is worth at player prices: the market value of the items you hand in next to the market value of the reward (quest mesos + items; pick 1: the best, random: the expected value), plus the NPC sell floor. When every item has a price, a <b>net</b> tag says whether doing the quest beats selling the items; otherwise it says how many items are priced. Prices: meso.watch sales, else classicmarket.kr posts (hover for sources and sample counts). Quest-only items don't count. A <b>Stack with</b> line lists other quests within 10 levels that need the same monster, so you can do them in one trip.</p"],
    ["0.12.3","2026-10-21T09:44:47+00:00","Oct 21, 2026 · classicmarket.kr prices",null,"<p>Prices now also come from <b>classicmarket.kr</b> trade posts (sellers' asks and buyers' buy orders, refreshed every 2 hours). Item pages show them as a line in Prices with the number of posts. Where meso.watch has no sales, Price check, Keep or sell and the Craft planner use the classicmarket.kr asking price (marked rough), and the FM Sniper's Sell helper offers \"Fill a buy order\". Only clean, unscrolled equips with an exact roll count; scrolled items, other rolls and \"make me an offer\" prices (0, 9,999...) are left out.</p"],
    ["0.12.2","2026-10-21T09:29:32+00:00","Oct 21, 2026 · Launch NPC shop prices",null,"<p>NPC shop prices are refreshed from meowdb's list, which has now re-read 26 of 31 shops at launch (the rest still show COT2 prices, and are marked as such). Changes include the Resident's Chairs (500,000 mesos) and several Lesser scrolls. The Citizenship shop prices follow. Item pages get a <b>Prices</b> box with the NPC shop, player shops and the NPC buy-back in one place, and a <b>NPC sells for less</b> tag (also in the Items list and FM Sniper) when a town shop beats the player price. Drop reports now say how many players confirmed them, with fresh reports (964, up from 873) and meso reports for 35 monsters. KPQ board names link to their classicrank.com profile.</p"],
    ["0.12.1","2026-10-21T09:09:37+00:00","Oct 21, 2026 · Character Builder: paste and go",null,"<p>Screenshots now apply the moment they're pasted: no more \"Apply to builder\" step or second copy of the form. One full-screen shot with the stat, equipment and skill windows open builds the whole character; snipping them one by one works too. Each screenshot shows as a thumbnail with a box on everything read; click it for the big view and the list. Skill points the screenshots can't show (say, your first 2nd job point) are asked for with one click. New Undo, Redo (Ctrl+Z / Ctrl+Y) and Reset buttons cover every change, a wrong paste included.</p"],
    ["0.12.0","2026-10-21T05:11:01+00:00","Oct 21, 2026 · Profiles and a new Settings",null,"<p>Settings now looks and works like the Grind Tracker's. New Profiles save your whole setup (header, sidebar, page size, menu and theme) under a name, switch between them, and share one as a code. Two come built in: Default (the site as it comes) and Danny's Default. Profile codes work in the tracker too, for the theme.</p"],
    ["0.11.4","2026-10-21T05:07:24+00:00","Oct 21, 2026 · Privacy page",null,"<p>New <b>Privacy</b> page (link at the bottom of every page): what the site and Grind Tracker keep about you (settings stay in your browser, screenshots are never uploaded, only Feedback notes and opt-in shared runs reach our server) and the usual fan-site disclaimers.</p"],
    ["0.11.3","2026-10-21T04:24:59+00:00","Oct 21, 2026 · Craft planner spacing",null,"<p>Craft planner cards no longer sit flush against each other, and the level, class and add-by-hand fields line up in rows with room between them.</p"],
    ["0.11.2","2026-10-21T02:49:42+00:00","Oct 21, 2026 · Smoother Home cards",null,"<p>Clicking a Home section card no longer flashes: the cards glide into place with sharp text instead of stretching and blinking.</p"],
    ["0.11.1","2026-10-21T02:26:37+00:00","Oct 21, 2026 · Feedback page",null,"<p>New <b>Feedback</b> page (link at the bottom of every page, or under More in the two-row layout): tell us about a bug, a wrong number or an idea. Notes go straight to the people running the site; add a Discord or in-game name if you'd like an answer. Nothing else about you is kept. The page sits in one centered column.</p"],
    ["0.11.0","2026-10-21T02:19:00+00:00","Oct 21, 2026 · Craft planner","new","<p>New page under Mesos and Trade: set your craft levels and add your inventory (the same screenshots Price check reads, or typed in), and it lists what you can craft now for a profit, what you're a few materials away from (with the best maps to farm them and an estimated time, or the cheapest way to buy them), and the best mix of crafts from what you hold. Prices are meso.watch medians; farming times use this site's 5% per kill assumption (real drop counts from shared grind tracker runs where 100+ kills were seen).</p"],
    ["0.10.7","2026-10-20T23:53:42+00:00","Oct 20, 2026 · Sidebar indent",null,"<p>Sidebar pages now sit indented under their section, the section icons are bigger and hang slightly left, and sections have a little more space between them, so the groups read at a glance.</p"],
    ["0.10.6","2026-10-20T23:16:13+00:00","Oct 20, 2026 · Builder and Skills moved",null,"<p><b>Character Builder</b> is now under <b>Training</b> (after Where to train) and <b>Skills</b> under <b>Maple Database</b>. The My Character section is gone. Old links still work, and a sidebar or Home order you saved in edit mode is kept.</p"],
    ["0.10.5","2026-10-20T21:55:00+00:00","Oct 20, 2026 · New header layout, bigger edit mode",null,"<p><b>Header:</b> on wider screens <b>Search everything</b> now sits on the left above the sidebar (and as wide as it), with a smaller <b>Settings</b> cog on the right in the same row.</p>\n      <p><b>Edit mode</b> (F1, or Settings › Toggle anchors) can now also move and scale the <b>title</b> and <b>tagline</b>, change the <b>sidebar's width</b> (drag the bar on its edge), put the <b>sidebar on the right</b>, drag <b>sidebar sections</b> and <b>Home cards</b> into your own order, and set how wide <b>Home cards</b> are. <b>Reset all</b> puts everything back.</p>"],
    ["0.10.4","2026-10-20T19:05:41+00:00","Oct 20, 2026 · Settings cog and Toggle anchors",null,"<p>The <b>Theme</b> button in the top-right corner is now a <b>cogwheel</b> that opens <b>Settings</b> as a pop-up over a blurred page, like Search. Same options as before: theme, share codes, layout and page size. Esc, × or a click outside closes it.</p>\n      <p><b>Toggle anchors</b> (in Settings, inspired by the ElvUI addon's /moveui): move <b>Search everything</b> and the <b>Settings</b> cog anywhere in the header. Labelled movers, a grid to snap to (8, 16 or 32), click a mover for exact X/Y and arrow nudges, drag Search's right edge to resize it, <b>Reset all</b> and <b>Lock</b>. Saved in your browser; phones keep the default header.</p>\n      <p>In anchor mode: <b>smart guide lines</b> (parts snap to the header's center and edges, the title and each other; hold Alt to place freely), <b>scale</b> each part (corner dot or the slider in its box), and <b>Colours</b>, the theme editor: change any colour with a live preview, then save it as your own theme or copy its code. <b>F1</b> opens and closes anchor mode (no more Chrome help tab), <b>Esc</b> is Done. Settings also has <b>Edit colours</b>.</p>"],
    ["0.10.3","2026-10-20T18:36:32+00:00","Oct 20, 2026 · Scroll check fixes","fix","<p><b>Scroll check:</b> the scroll you hover is the one that ticks (it used to tick a slot lower down), and a scroll the mouse already covered when you started sharing scans too. The price table now lists only scrolls during a scroll check; the picture upload still prices everything. The tab grid has no sideways scrollbar, every slot is the same size, and it follows the scroll you hover. Long scroll names no longer push the prices out of the list.</p"],
    ["0.10.2","2026-10-20T18:13:15+00:00","Oct 20, 2026 · Scroll check polish",null,"<p><b>Scroll check:</b> a live line says which scroll the tooltip under your mouse is (or that it can't read that one yet, so you can pick it in the table), the scanned list adds up repeats (×2) and shows what the scanned scrolls are worth, and <b>Start over</b> clears the scans. Fixed: scrolls in the top row of the Use tab couldn't be scanned (their tooltip covers the window's edge). Tested against every scroll in the game files, and with the tab scrolled.</p>"],
    ["0.10.1","2026-10-20T17:33:08+00:00","Oct 20, 2026 · Scroll check reads real tooltips",null,"<p><b>Scroll check</b> now reads the game's real scroll tooltips (from Danny's screenshots): the bold name, and the description even when it wraps onto a second or third line. Letters it hasn't seen yet are learned from tooltips it could still place, so it gets better the more you scan.</p>"],
    ["0.10.0","2026-10-20T17:20:48+00:00","Oct 20, 2026 · FM Sniper tools","new","<p>The FM Sniper now has tool tabs. <b>Shopping trip:</b> type how many mesos you have and it picks the best deals you can afford, grouped by channel so you change channel as little as possible, with a copyable list. <b>Crafting flips:</b> buy the ingredients (live listings first), craft, and sell the result at its usual price; recipes and fees from the game files. <b>Sell yours:</b> what to list an item at to be the cheapest, sell fast, match the usual price or wait, and what an NPC pays. <b>Watch list:</b> a target price per watched item, with alerts in the tab title, a browser notification or a sound when a newer list hits it. <b>Movers:</b> the biggest rising and falling prices. <b>Deal lifetimes:</b> from every past listing snapshot, how often and how fast deals of each kind disappear.</p>\n      <p><b>On the list:</b> listings under what an NPC pays are flagged (buy and vendor them), as are ones an NPC shop sells cheaper. New <b>Best flip</b> sort (mesos under × how often it sells), a <b>volatile</b> tag when sale prices spread wide, <b>Needed by me</b> (what your Keep or sell list still needs), presets plus your own saved ones, how long a listing has been up, a market mood tile, and keys: j/k to move, w to watch, c to copy, Enter to open.</p"],
    ["0.9.1","2026-10-20T17:11:09+00:00","Oct 20, 2026 · Scroll check","new","<p><b>Price check › Scroll check:</b> scrolls of one tier share a single picture (Lesser, Intermediate, Greater, Chaos: 52 each in the game files), so screenshots could only guess which one you had. Now you can share your game window with the page, open the <b>Use</b> tab and rest the mouse on each scroll: its tooltip is read, the slot gets a green tick, and the named scroll lands in the price table with its meso.watch price. Nothing leaves your browser. Works in Chrome, Edge and Firefox on a computer; tuned on drawn tooltips for now, real game tooltips next.</p>"],
    ["0.9.0","2026-10-20T10:24:41+00:00","Oct 20, 2026 · FM Sniper","new","<p><b>FM Sniper</b> (Mesos and Trade): every item meso.watch sees listed in the Free Market right now, next to what it usually sells for. Each row shows the listed price, the usual price and the range half of sales landed in, a small bar of where the listing sits in that range, the <b>% of value</b> and how many <b>mesos under</b> (and the whole stack's gap). The best three deals sit on top as cards; tiles up top count what's under value and show the best find and the biggest gap.</p>\n      <p><b>Views:</b> Deals, Over value (listings over the usual price are marked <b>rising</b> when meso.watch's trend is up: demand may be catching up) and Everything listed. <b>Filters:</b> type, max price, at least N% under, sales seen, hide rough prices, compare with the low end instead of the median. <b>Sorts:</b> best deal, lowest % of value, most mesos under, biggest stack gap, cheapest, sells fastest and more; click a column title to sort by it.</p>\n      <p><b>Trust:</b> a price from under 5 sales is marked rough, under 25% of value says \"check it\" (often a typo or the wrong item), and the deal labels and best-deal score are this site's own cut-offs, explained on the page. <b>Watch</b> items with ☆, see listings that are <b>new</b> since your last visit, copy an item's price, channel and seller in one click, and share your filters with Copy link. On the website the page picks up a newer list on its own while it's open and tells you when a watched item comes up cheap.</p"],
    ["0.8.1","2026-10-20T09:29:41+00:00","Oct 20, 2026 · Footer, app icon, offline on the new address","fix","<p><b>Footer:</b> \"Site version\" and the meso.watch status line now sit in a footer at the very bottom of every page, below the sidebar, with Changelog and Credits centered under them. <b>Offline:</b> maplestory.scumlord.studio now works offline and installs as an app too (before, only the old GitHub Pages address did). <b>Icon:</b> the browser tab and home-screen icon is an Orange Mushroom on a purple tile. <b>Character Builder</b> shows a picture of your character in the chosen gear and weapon (from maplestory.io; hidden if it can't load). <b>Item pages:</b> the cheapest live listing says how long ago listings were updated instead of a UTC time.</p"],
    ["0.8.0","2026-10-20T07:39:35+00:00","Oct 20, 2026 · New navigation","new","<p>The site has grown a lot, so the sections are reorganized and every page is now listed in a sidebar: <b>Grind Tracker</b>, <b>My Character</b> (Character Builder, Skills), <b>Training</b> (Where to train, Path Planner, EXP/hr calculator, Kerning PQ), <b>Victoria Island</b> (World Map, Map Navigator), <b>Maple Database</b> (Items, Monsters, Quests) and <b>Mesos and Trade</b> (Price check, Keep or sell, Crafting, Citizenship). Each page gets a game sprite picked at random from things that fit it every time you load the site; the snail on Home stays. Changelog and Credits moved to the bottom of the page.</p>\n      <p>Theme now also has <b>Layout</b> (Sidebar, Basic mode without sprites, or the old Two rows) and <b>Page size on wide screens</b> (1 to 5): on windows 1700px wide or more the page now uses more of the screen and everything is a bit bigger (size 3 by default; 1 is the old fixed width). All text is about 8% bigger everywhere. Phones keep the swipeable two rows. Old links still open the same pages.</p"],
    ["0.7.4","2026-10-20T06:03:55+00:00","Oct 20, 2026 · meso.watch status on Home","update","<p>Under \"Site version\" at the bottom of Home, a new line shows the state of the meso.watch prices: how many items have a price, the last day of sales they cover, and how many live listings there are and how long ago they were updated.</p"],
    ["0.7.3","2026-10-20T04:49:12+00:00","Oct 20, 2026 · Launch-client formulas","update","<p>Damage, defense, EXP and meso numbers now follow the launch game client instead of the second closed test, as read by the <a href=\"https://osmsdataexplorer.com/#formulas\" target=\"_blank\" rel=\"noopener\">OSMS Data Explorer</a> formulas page. <b>Mastery</b> counts ×0.7 (was ×0.8), so minimum hits are a bit lower. <b>Magic</b> damage uses INT/125 (was /100), about 10% less at 100 INT. <b>Damage taken</b> (Danger) uses the new defense formula with flat DEF/25 and level/10 cuts. <b>Iron Arrow</b> loses 20% per extra target, compounding (1, 0.8, 0.64, 0.512). <b>EXP</b> for levels 90-99 is 2.1× the level before (Lv 90 needs 11.9M), and the whole table counts as confirmed now. <b>Mesos</b> per kill are floor(2.1 × monster level) + 3, ±10%, on about 67% of kills (fitted to in-game captures by azzy), roughly 30% less than the old estimate. <b>Party</b> EXP bonus adds 5% for each extra member who hits the monster (4 players: 45%, was 30%). <b>Crafting</b> stops at Lv 8, and <b>Citizenship</b> grades need 1,500 to 32,000 contribution.</p"],
    ["0.7.2","2026-10-19T23:54:24+00:00","Oct 19, 2026 · Ability point boxes fixed","fix","<p><b>Character Builder:</b> the STR, DEX, INT and LUK boxes no longer overlap each other or run past the edge of the card. The same fix covers the skill boxes in \"Import from screenshots\".</p"],
    ["0.7.1","2026-10-19T22:40:06+00:00","Oct 19, 2026 · Version numbers","update","<p>The site has a version number now, shown next to \"Site version\" on Home. Every entry in this changelog is one version, counted from the first build on Oct 6 (0.1.0) to today; the middle number went up for the big additions (monster and item databases, Home page, EXP/hr calculator, players' shared runs, Search everything, the phone app). The <b>Grind Tracker</b> app's own patch notes moved to <a href=\"https://maplestory.scumlord.studio/#g=trk\" target=\"_blank\" rel=\"noopener\">Grind Tracker</a> (and Help › Patch notes in the app), so this page is only about the site.</p"],
    ["0.7.0","2026-10-19T20:27:33+00:00","Oct 19, 2026 · Phone app, faster first load, keep or sell in the price check","update","<p><b>Phones:</b> \"Add to Home Screen\" on the GitHub Pages site now opens it full-screen like an app, and once opened it works offline. The page there loads about 3× less up front (item icons and minimaps follow a moment later). <b>Price check</b> marks every item <b>Keep</b> or <b>Sell</b> with the Keep or sell rules and adds up what you can <b>sell now</b>. <b>Character Builder:</b> compare two jobs side by side at one level (e.g. Fighter vs Page at 45). <b>Where to train</b> remembers its settings and your \"Use this in Where to train\" build after a reload. <b>Credits</b> lists when each data source was last updated. Typing a huge number in a Where to train stat box no longer breaks the phone layout.</p"],
    ["0.6.12","2026-10-19T19:21:10+00:00","Oct 19, 2026 · Hunter and Crossbowman area attacks back","fix","<p>The Oct 17 game-file update renamed <b>Arrow Bomb</b> and <b>Iron Arrow</b> (they lost their \": Bow\" / \": Crossbow\" endings). Since then Where to train ranked Bowmen 30+ as single-target (a Lv 45 Bowman's top map went from about 137k to 285k EXP/hr now that Arrow Bomb counts again), and the Hunter and Crossbowman class-guide builds dropped the SP they put into those skills. Also: a Lv 10 Warrior can't have Slash Blast yet (1 SP, and it needs Power Strike 1 first), so Where to train and the Path Planner no longer count it at 10.</p"],
    ["0.6.11","2026-10-19T19:14:57+00:00","Oct 19, 2026 · Sturdier, quicker, better on phones","fix","<p><b>Phones:</b> the page now sizes itself to your screen (it used to load zoomed out at desktop width), and the section and page buttons are one swipeable row each, so content starts much higher. <b>Speed:</b> the page starts about 20% faster, and Crafting, Keep or sell and the Quest Database switch in 2-3× quicker (long tables draw as you scroll). <b>Fixes:</b> old saved settings or edited share links can no longer break Citizenship, the Character Builder, Path Planner, World Map, Crafting or a monster page; a huge level typed into Where to train is capped instead of breaking the accuracy line; the Grind Tracker pages ignore anything odd from the server; Price check says when a file isn't a picture, and it and the Builder's screenshot import read your first picture in about half a second instead of 2-5; Search puts monsters and real items ahead of the letter chairs and shows the ID when two items share a name; Esc or a click elsewhere closes the Theme box, a cut-off theme code says so, and Search hands focus back.</p"],
    ["0.6.10","2026-10-18T21:57:33+00:00","Oct 18, 2026 · Back and Forward","update","<p><b>← →</b> buttons left of the section buttons step back and forward through the pages and places you opened (a monster, item or skill page, a World Map island, area or card, a quest line). Your browser's Back button does the same now, instead of dropping you on Home.</p"],
    ["0.6.9","2026-10-18T21:22:55+00:00","Oct 18, 2026 · Themes, same as the Grind Tracker","update","<p>A <b>Theme</b> button at the top lets you pick any of the Grind Tracker's colour themes, or paste a tracker theme code (MSCT1...) to wear your own. <b>Copy code</b> gives a code the tracker accepts. Default is this site's own look, and it's now the tracker's default too, so the two match side by side.</p"],
    ["0.6.8","2026-10-18T21:08:29+00:00","Oct 18, 2026 · Little sprites on Home","update","<p>Each Home card has a small in-game icon by its name, and an opened card shows one for every page in it (a Snail for the Grind Tracker, an Orange Mushroom for Monsters, Teleport for the Map Navigator and so on).</p"],
    ["0.6.7","2026-10-18T20:34:45+00:00","Oct 18, 2026 · Bank in the price check, easier screenshot import","update","<p><b>Price check</b> reads your <b>bank</b>: add screenshots scrolled down a bit at a time and the overlapping rows are counted once (same for scrolled inventory tabs). With the bank open, the inventory beside it is left out; bank mesos are shown. <b>Character Builder</b> import adds screenshots up in any order: equipment before the stat window no longer reads as \"over the budget\". Each screenshot gets a chip you can remove, and <b>Reset</b> clears them all. Worn gear counts at its base stats (an average drop); edit the numbers before applying if yours are better.</p"],
    ["0.6.6","2026-10-18T17:34:10+00:00","Oct 18, 2026 · Site version on Home","update","<p>The bottom of Home shows when this copy of the site was built, so you can tell at a glance that an update has reached you.</p"],
    ["0.6.5","2026-10-18T17:21:35+00:00","Oct 18, 2026 · Respawns use each map's mob capacity","update","<p><b>Where to train</b>, the <b>Path Planner</b>, the World Map and monster pages now cap respawns with each map's <b>mob capacity</b> from the game files: how many monsters it keeps alive for one player (OSMS, worked out from map size and checked against in-game counts). We used to assume 75% of spawn points everywhere; most maps keep about half. Area-attack EXP/hr drops on big maps (for example a level 45 F/P Wizard on B2 Subway Depot, about 238k to 157k an hour), and the top maps reshuffle. Single-target builds barely change. Parties of up to 5 get no extra monsters (OSMS's estimate, not yet confirmed).</p"],
    ["0.6.4","2026-10-18T17:12:07+00:00","Oct 18, 2026 · Game data updated to the Oct 17 export","update","<p>Rebuilt from the newest OSMS game-file export (Oct 17; was Oct 6). <b>The Filing Error</b> now asks for 25 Torn Ledger Pages (was 50). Coconut sells to NPCs for 10 mesos (was 145). Blue Mushroom in L Forest III has a 10-minute respawn, so it moves to timed spawns and out of Where to train. Wild Kargo's Area has 14 Wild Kargos (was 13). New item: Lie Detector Test. Small map, portal and skill-range fixes. Player drop reports and shop prices are unchanged.</p"],
    ["0.6.3","2026-10-18T17:01:00+00:00","Oct 18, 2026 · Fixes and polish","update","<p><b>Where to train</b> shows its ranking as soon as you open it (it was empty until you changed a setting). The site reopens on the page you last used instead of always on Home. <b>Import from screenshots</b> now reads every skill level (The Eye of Amazon was missed). Faster first load: the page is about a quarter smaller (item, NPC and monster pictures re-saved smaller, pixel for pixel the same), and Crafting and Keep or sell build their tables when you open them. Small touches: soft shadows on panels, gentle fade when pages and info boxes open, themed file buttons, focus rings and scrollbars. Motion is off if your system asks for reduced motion.</p"],
    ["0.6.2","2026-10-18T16:53:12+00:00","Oct 18, 2026 · Home cards grow when clicked","new","<p>Click a section card on Home and it grows into a big card at the top with a short description and its pages (the Grind Tracker one has the download). Click it again to shrink it back.</p"],
    ["0.6.1","2026-10-18T16:23:25+00:00","Oct 18, 2026 · Grind Tracker section","new","<p>The <b>Grind Tracker</b> is now its own section, first in the menu and on Home: Overview (what it does and the download), How to use, Shared runs, and the KPQ leaderboard.</p"],
    ["0.6.0","2026-10-18T16:03:51+00:00","Oct 18, 2026 · Search everything, more share links","new","<p><b>Search everything</b> (top of the page, or press <b>Ctrl K</b> or <b>/</b>): monsters, items, maps, quests and skills in one box. Parts of words work, so \"or mu cap\" finds Orange Mushroom Cap. <b>@mob</b>, <b>@item</b>, <b>@map</b>, <b>@quest</b> and <b>@skill</b> narrow it, and <b>@drop</b> lists the monsters players have seen drop an item.\n      <b>Copy link</b> buttons now also on World Map cards, the Map Navigator, Where to train and the Quest Database. Monster drops are split into Equip, Use, Etc and Quest.</p"],
    ["0.5.7","2026-10-18T14:56:41+00:00","Oct 18, 2026 · KPQ leaderboard","new","<p>The <b>Grind Tracker</b> page has a <b>KPQ leaderboard</b>: the fastest Kerning PQ clears by tracker players (1st stage to the end of the Last stage), split by Bonus and Rush, one line per party. Needs grind tracker 0.2.40 or newer with sharing on.</p"],
    ["0.5.6","2026-10-18T14:38:01+00:00","Oct 18, 2026 · Grind Tracker page","new","<p>New <b>Grind Tracker</b> page under Your character: what our Windows grind tracker does, a download link, and everything its players have shared so far (EXP/hr and mesos/hr by map, confirmed drops by monster, best time of day to farm).</p"],
    ["0.5.5","2026-10-18T10:27:27+00:00","Oct 18, 2026 · Inventory price check","new","<p>New <b>Towns and trade › Price check</b> page: paste screenshots of your inventory's Equip, Use and Etc tabs and it lists every item and count with a suggested player-shop price (meso.watch median, NPC price when there's no player data) and what the lot is worth. Uses the grind tracker's inventory reader, all in your browser.</p"],
    ["0.5.4","2026-10-18T01:19:15+00:00","Oct 18, 2026 · Player-shop prices refreshed","update","<p>Player-shop prices updated from a fresh <a href=\"https://meso.watch/\" target=\"_blank\" rel=\"noopener\">meso.watch</a> export: 824 items now have a price (up from 459), read Oct 17.</p"],
    ["0.5.3","2026-10-17T21:52:05+00:00","Oct 17, 2026 · Real potion costs","new","<p>Grind tracker 0.2.6 counts the potions, food and arrows players use (from their quick slots). Where to train and World Map cards add it to the <b>players:</b> line (\"pots/ammo 1,200/hr\"), and <b>Frugal</b> mode uses that real spending instead of its estimates on maps where 3+ players near your level shared runs, marked \"(players' costs)\".</p"],
    ["0.5.2","2026-10-17T21:14:33+00:00","Oct 17, 2026 · Best time to farm","new","<p>Where to train and World Map cards get a <b>best time:</b> line (for example \"9 PM-12 AM (+15%)\"): the 3 hours of the day, in your time zone, when grind tracker players farm that map fastest compared with their own usual speed there. It appears once 3+ players have runs on the map in at least two time blocks (tracker 0.2.5 and later).</p"],
    ["0.5.1","2026-10-17T19:33:47+00:00","Oct 17, 2026 · Players' EXP/hr","new","<p>Where to train: under each map's estimated EXP/hr, a <b>players:</b> line shows what grind tracker players within 5 levels of you really got there (solo or party, like your setting). It only appears once 3+ different players or parties have shared runs on that map; runs under half or over double the typical one are left out. It also shows deaths per hour there (from tracker 0.2.2), and the same line is on World Map cards. New Mode <b>Farmed by players</b> lists only maps with players' runs, fastest for them first. Confirmed Drops now also give a likely range (\"1 per 11 kills (likely 8-15)\"), a statistics estimate that narrows as more kills are shared.</p"],
    ["0.5.0","2026-10-17T18:50:18+00:00","Oct 17, 2026 · Confirmed Drops","new","<p>Monster and item pages get a <b>Confirmed Drops</b> box once players of our grind tracker (a Windows app that reads the game screen) share their runs: kills counted and what they picked up, as \"about 1 per X kills\". It only sees the sharing player's own pickups, so real rates are at least that. Empty until runs come in.</p"],
    ["0.4.7","2026-10-17T04:38:17+00:00","Oct 17, 2026 · The List removed","update","<p>The kill-stealer list tab is gone.</p"],
    ["0.4.6","2026-10-17T04:36:18+00:00","Oct 17, 2026 · Collapsible crafting sections","update","<p>Crafting: every section (Masters and profession quests, Craft levels, Cheapest way to level, Recipes, Raw materials) now folds up when you click its heading. Masters and profession quests starts folded.</p"],
    ["0.4.5","2026-10-16T20:50:14+00:00","Oct 16, 2026 · Item and monster filters","update","<p>Items: the <b>Type</b> filter now also picks <b>Weapons</b>, <b>Armor</b> or <b>Accessories</b> (Slot then lists only that group's slots), and a <b>Reset filters</b> button puts every filter back to its default. Monsters: new <b>Weak to</b> filter (Fire, Ice, Lightning, Poison, Holy or no weakness), from the launch game files' element data; Reset filters clears it too.</p"],
    ["0.4.4","2026-10-16","Oct 16, 2026 · Fresh meowdb drops","update","<p>Monster drops re-pulled from meowdb player reports: 825 confirmed drops (was 708), 122 new reports across 66 monsters, 2 removed by meowdb (Mithril Ore from Fire Boar, Diamond Ore from Evil Eye). Shade has drops listed for the first time; Wraith, Zombie Lupin and Dark Stone Golem got the most new ones.</p"],
    ["0.4.3","2026-10-14T01:56:20+00:00","Oct 14, 2026 · Skill database","new","<p>New <b>Skills</b> page under Databases: all 90 1st and 2nd job skills from the launch game files, searchable by name, job or effect, with class, job, advancement and type filters. Click a skill for its page: description, effect at every level, the skill it needs and the skills it unlocks.</p"],
    ["0.4.2","2026-10-13T12:34:47+00:00","Oct 13, 2026 · Character Builder: import from screenshots","new","<p>Drop, pick or paste screenshots of your <b>Character Stat</b>, <b>Equipment Inventory</b> and <b>Skill Inventory</b> windows into the new box at the top of the Character Builder. It reads level, STR/DEX/INT/LUK, worn items (by icon) and skill levels, shows them for a check, then fills the build. The stat window shows totals, so the read gear's base stats are taken off to get your AP. Reading happens in the page; nothing is uploaded.</p"],
    ["0.4.1","2026-10-13T03:39:50+00:00","Oct 13, 2026 · Monsters: find who drops an item","update","<p>The Monsters list has a <b>Drops item</b> box: type or pick an item and only the monsters players report dropping it stay (from meowdb drop reports; + = net confirmations). A <b>Reset filters</b> button clears search, type, item and sorting.</p"],
    ["0.4.0","2026-10-13T02:28:50+00:00","Oct 13, 2026 · EXP/hr calculator","new","<p>New <b>EXP/hr calculator</b> under Your character: note your EXP, start the timer, train, then type the new EXP. It gives your real EXP per hour, % of a level per hour, time to the next level (or a goal level) and how it compares with our Where to train estimate for that map. Sessions save in your browser. Idea from <a href=\"https://mapleexp.com/\" target=\"_blank\" rel=\"noopener\">MapleEXP</a>.</p"],
    ["0.3.10","2026-10-12T05:47:23+00:00","Oct 12, 2026 · Fresh meowdb drops","update","<p>Monster drops re-pulled from meowdb player reports: 708 confirmed drops (was 580), 128 new reports across 65 monsters, none removed. New include Mano and Mushmom crafting catalysts, and many more equips, scrolls and ores.</p"],
    ["0.3.9","2026-10-10T00:28:47+00:00","Oct 10, 2026 · Undervalued maps","new","<p>World Map has an <b>Undervalued maps</b> button: green dots are quieter training spots (maps guides call overflow, quieter or little-known, or that have the same monsters as a famous map), red rings are maps the guides call busy. Each card says why, what to go instead of, sources, and the dearest drops reported there. It ignores your class and level.</p"],
    ["0.3.8","2026-10-09T19:18:14+00:00","Oct 9, 2026 · World Map: click, not hover","update","<p>On the World Map (and the Sleepywood map), hovering a dot now only shows its name and monster levels. The card on the right changes only when you click a dot, so brushing over other dots no longer replaces what you're reading.</p"],
    ["0.3.7","2026-10-09T13:12:12+00:00","Oct 9, 2026 · Player-shop prices","new","<p>Items now show what players pay in player shops (median sale price from <a href=\"https://meso.watch/\" target=\"_blank\" rel=\"noopener\">meso.watch</a>): a <b>Players</b> column in Items, a line on each item page, a \"players ~\" line and sort in Keep or sell, and a <b>Loot price</b> setting in Frugal mode to value loot at player prices instead of NPC prices.</p"],
    ["0.3.6","2026-10-08T18:19:47+00:00","Oct 8, 2026 · Frugal mode counts loot",null,"<p>Frugal mode's net now includes ETC items and potions sold to NPCs (meowdb drop reports, at an assumed 5% a kill each; 10%, 15% or off in the new <b>Loot sold to NPCs</b> setting).</p"],
    ["0.3.5","2026-10-08T18:07:39+00:00","Oct 8, 2026 · Potion drops in Frugal mode",null,"<p>Frugal mode lists the healing and mana potions each map's monsters drop (meowdb player reports) under the map name.</p"],
    ["0.3.4","2026-10-08T17:01:20+00:00","Oct 8, 2026 · Basic attacks, gentler hit costs","new","<p>Where to train: <b>Basic attack (no skills)</b> under Attack ranks maps with plain hits (no MP; arrows and stars still cost). Frugal mode has a <b>Monsters that hit you</b> setting (default 1 in 4, was every one), so damage taken is less harsh.</p"],
    ["0.3.3","2026-10-08T16:52:48+00:00","Oct 8, 2026 · Where to train uses your stat window","new","<p>The damage-per-second box is gone. Type what your in-game stat window shows instead: Attack range, Accuracy, Evasion, Max HP and Weapon Def (Magicians: Magic and INT). Empty boxes fall back to the Character Builder's default build for your level, which is also better than the old 20 × level guess.</p"],
    ["0.3.2","2026-10-08T16:42:53+00:00","Oct 8, 2026 · Frugal mode in Where to train","new","<p>Where to train has a <b>Mode</b> picker. <b>Frugal (meso positive)</b> shows only maps where monster mesos cover your potions and ammo, skips Danger/Lethal maps, and ranks what's left by EXP. Each map shows its net mesos per hour. Damage taken is an estimate; see the how-to box.</p"],
    ["0.3.1","2026-10-08T14:53:33+00:00","Oct 8, 2026 · Shorter intro, closed how-to boxes",null,"<p>The text under the title is now one line. The how-to boxes at the top of each page start closed; click one to open it.</p"],
    ["0.3.0","2026-10-08T14:49:34+00:00","Oct 8, 2026 · Home page and sections","new","<p>New <b>Home</b> page with every tool and what it's for. The top bar now shows five sections (<b>Your character</b>, <b>Databases</b>, <b>World</b>, <b>Towns and trade</b>, <b>More</b>); pick one to see its pages. Clicking the site title goes home. Links between pages (map names, items, monsters, Route here) work as before.</p"],
    ["0.2.13","2026-10-08T11:42:48+00:00","Oct 8, 2026 · KPQ guide","new tab","<p>New <b>KPQ</b> tab: how to get in (4 players, level 21+, channels 3-5 only), Proof of Companionship, every stage with its minimap and monster spots, Cloto's coupon questions, all rope / platform / barrel combinations, King Slime's stats, the monsters inside and what players get from Companion's Magic Box. Game-file data plus meowdb's KPQ guide.</p"],
    ["0.2.12","2026-10-08T03:19:06+00:00","Oct 8, 2026 · Sleepywood map easier to find","fix","<p>The Sleepywood area map now has a <b>Sleepywood area map</b> button above the World Map, an <b>Open Sleepywood map</b> label on the map itself and a button in Sleepywood's card, and it opens wider so the map names don't overlap. Before, it only opened by clicking the small square dot.</p"],
    ["0.2.11","2026-10-08T01:58:52+00:00","Oct 8, 2026 · Sleepywood map","update","<p>On the World Map, clicking Sleepywood opens a map of the Sleepywood area: all its maps (dungeons, Ant Tunnel, Evil Eye caves, Sanctuary, Deep Forest of Patience) joined by their walkable exits, each with the usual hover card. Monster search lights up dots there too.</p"],
    ["0.2.10","2026-10-08T00:25:50+00:00","Oct 8, 2026 · Map names open map info","maps","<p>Clicking a map name anywhere on the site now opens that map's card on the <b>World Map</b> (monsters, EXP/hr, danger, NPCs, quests, minimap) instead of the navigator. Press <b>Route here</b> on the card for directions.</p"],
    ["0.2.9","2026-10-08T00:21:34+00:00","Oct 8, 2026 · Fresh meowdb drop reports","data","<p>Re-pulled meowdb's player drop reports: 82 new confirmed drops, 3 no longer confirmed. Bosses, KPQ and jump-quest monsters now show their reports too (Mano, Mushmom, Zombie Mushmom, Jr. Balrog, King Slime and more had none before). Updates monster pages, item pages, Crafting and Keep or sell.</p"],
    ["0.2.8","2026-10-08T00:09:44+00:00","Oct 8, 2026 · Items: new filters","update","<p>Items tab has a <b>Get it from</b> filter (monster drops, NPC shops, crafting or quest rewards), a <b>Used for</b> filter (crafting components, items quests ask for) and a <b>Hide quest items</b> filter (on by default) for letters, proofs and other quest-only items. Quest item pages are tagged \"quest item\".</p"],
    ["0.2.7","2026-10-07T23:59:52+00:00","Oct 7, 2026 · Item database","new","<p>New <b>Items</b> tab: all 2,220 items in the launch game files, searchable by name or by a monster that drops it, with type, slot, job and \"has a known source\" filters. Click any item (or any item icon or name anywhere on the site) for its page: stats, description, monsters that drop it, NPC shops, recipes, quest rewards, quests and recipes that want it, sell price and similar gear. Monster pages link their drops to item pages, and item pages link back to monster pages.</p"],
    ["0.2.6","2026-10-07T21:11:42+00:00","Oct 7, 2026 · World map monster search","update","<p>World Map has a <b>Find a monster</b> box: type a monster and every place it spawns lights up (other dots dim), with a count per island. Hovering a lit dot opens the minimap of the map where it spawns most.</p"],
    ["0.2.5","2026-10-07T20:25:52+00:00","Oct 7, 2026 · World map spawns","update","<p>The World Map card's minimap now shows where each monster spawns, one color per monster, with a legend. It sits right under the map list.</p"],
    ["0.2.4","2026-10-07T20:17:12+00:00","Oct 7, 2026 · World map","new tab","<p>New <b>World Map</b> tab: the game's own Maple Island and Victoria Island maps with a dot for every place. Hover a dot to see its maps, monsters (level, HP, EXP), danger and EXP/hr at your class and level (estimate), NPCs and their quests, cab and potion shop, and a minimap. Click to pin; map names open the Map Navigator.</p"],
    ["0.2.3","2026-10-07T14:20:06+00:00","Oct 7, 2026 · Navigator: no taxi","navigator","<p>Map Navigator has a <b>No taxi</b> box: tick it to get a walking-only route (fewest maps) instead of cab rides between towns.</p"],
    ["0.2.2","2026-10-07T14:08:43+00:00","Oct 7, 2026 · Map navigator","new tab","<p>New <b>Map Navigator</b> tab. Clicking any map name on the site now opens it as your destination: pick where you're starting (any map or a town) and it shows the quickest route map by map, with which numbered exit to take on each minimap, cab rides between towns and Shanks' ship off Maple Island. Travel time is an estimate (30 s a map, 45 s a cab), same as the Path Planner.</p"],
    ["0.2.1","2026-10-07T13:40:43+00:00","Oct 7, 2026 · Monster pages","monsters","<p>Clicking a monster (in the Monsters tab or any monster name on the site) now opens its own page: stats, every spawn place, drops, mesos, attacks and quests, plus <b>Best maps to farm it</b>: the maps it spawns on, ranked by how many you'd kill per hour at your class and level (estimate), with danger, EXP/hr and a minimap showing where it spawns. Each page has a shareable link.</p"],
    ["0.2.0","2026-10-07T05:28:13+00:00","Oct 7, 2026 · Monster database","new tab","<p>New <b>Monsters</b> tab: all 71 monsters you can meet at launch (field monsters, bosses, jump quests, KPQ, 2nd job test), searchable by name, map or drop. Each card shows every stat in the launch game files (HP, MP, EXP, attack, defense, accuracy, avoid, speed, knockback, regen, elements), its attacks and skills, every spawn map with respawn time, meowdb player drop and meso reports, and the quests and recipes that want it.</p"],
    ["0.1.1","2026-10-06T23:20:31+00:00","Oct 6, 2026 · Backup grind maps","planner","<p>Path Planner grind steps now list up to 2 backup maps for when the pick is crowded: monsters within 5 levels on average and at least 60% of the EXP/hr, with the percentage shown.</p"],
    ["0.1.0","2026-10-06T19:01:29+00:00","Oct 6, 2026 · Launch game data","data","<p>Every tab now uses the OSMS <b>Public Release</b> export (Oct 6) instead of Closed Online Test 2.</p>\n      <ul>\n        <li><b>Quests:</b> EXP changed on 158 quests and mesos on 130. Examples: Jane's three Challenges 6,300 → 9,940 EXP; John's Deep Forest baskets 6,581 → 25,900; Jane and the Mushroom 2,021 → 1,610; Olaf's and Teo's early quests 84 → 124.</li>\n        <li><b>New quests:</b> 6 Ellinia level 28 quests (The Filing Error, Chief Stan's Signature, Repairing the Book, The Faded Ink, The Dark Lord's Signature, We Hold Your Place) and 12 event quests (Halloween, Founder's First Step, The Marks We Leave Behind). 35 more citizenship quests.</li>\n        <li><b>Removed quests:</b> 59, nearly all El Nath, Forgotten Hollow and Orbis. These were already hidden here as not in the launch.</li>\n        <li><b>Monsters:</b> 23 changed. Most level 20-40 monsters give 5-10% less EXP and have 1-2 more avoid (Lupin 82 → 75, Croco 155 → 146, Wraith 132 → 122, Drake 142 → 133). Tauromacis 300 → 337 and Taurospear 350 → 429 EXP. Green Mushroom is no longer undead. Fairy 2 is gone.</li>\n        <li><b>Maps:</b> The Murky Swamp is new and open.</li>\n        <li>Training spots, path plans, quest EXP and the keep-or-sell list all recalculate from the new numbers. Guides and mechanics from meowdb and maplestory.quest are still from COT2.</li>\n        <li>Added this Changelog tab.</li>\n      </ul"]
  ];
  if (typeof module !== "undefined" && module.exports) module.exports = LOG; else root.SiteChangelog = LOG;
})(typeof window !== "undefined" ? window : globalThis);
